package com.kuiya.filter;
import android.content.*;import android.content.res.Configuration;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.*;import androidx.core.view.*;import com.google.android.material.color.DynamicColors;
public class SettingsActivity extends AppCompatActivity{
 android.content.SharedPreferences p;public void onCreate(Bundle b){applyTheme();super.onCreate(b);setContentView(R.layout.activity_settings);setupBars(R.id.settingsRoot);p=getSharedPreferences("kuiya",0);RadioButton k=findViewById(R.id.kuiyaTheme),s=findViewById(R.id.systemTheme);if("system".equals(p.getString("theme","kuiya")))s.setChecked(true);else k.setChecked(true);RadioGroup g=findViewById(R.id.themeGroup);g.setOnCheckedChangeListener((x,id)->{p.edit().putString("theme",id==R.id.systemTheme?"system":"kuiya").apply();Toast.makeText(this,"テーマを変更しました。次回起動から適用します",Toast.LENGTH_SHORT).show();});findViewById(R.id.settingsToolbar).setOnClickListener(v->finish());findViewById(R.id.openFilterButton).setOnClickListener(v->startActivity(new Intent(this,FilterActivity.class)));}
 void applyTheme(){if("system".equals(getSharedPreferences("kuiya",0).getString("theme","kuiya")))DynamicColors.applyToActivityIfAvailable(this);}void setupBars(int id){WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(android.graphics.Color.TRANSPARENT);boolean light=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)!=Configuration.UI_MODE_NIGHT_YES;WindowInsetsControllerCompat c=WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView());c.setAppearanceLightStatusBars(light);c.setAppearanceLightNavigationBars(light);View root=findViewById(id);ViewCompat.setOnApplyWindowInsetsListener(root,(v,in)->{androidx.core.graphics.Insets x=in.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(x.left,x.top,x.right,x.bottom);return in;});ViewCompat.requestApplyInsets(root);}
}
